        var cacheKey = $"{chatId}_{userId}";
        var cacheValue = $"Message from @{username.ToLower()}";

        MemoryCache.Default.Add(cacheKey, cacheValue, new CacheItemPolicy { AbsoluteExpiration = DateTimeOffset.UtcNow.AddHours(1) });

